<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#111}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:5px;vertical-align:top}th{background:#0f172a;color:white}.muted{color:#666;font-size:10px}</style></head><body><h2>Login Tracker Report</h2><p class="muted">Generated: {{ $generatedAt }}</p><table><thead><tr><th>Date</th><th>User</th><th>Email</th><th>Event</th><th>IP</th><th>Browser</th><th>Device</th><th>Description</th></tr></thead><tbody>@foreach($records as $item)<tr><td>{{ optional($item->created_at)->format('Y-m-d H:i') }}</td><td>{{ $item->user->name ?? 'System' }}</td><td>{{ $item->email }}</td><td>{{ $item->event }}</td><td>{{ $item->ip_address }}</td><td>{{ $item->browser }}</td><td>{{ $item->device }}</td><td>{{ $item->description }}</td></tr>@endforeach</tbody></table></body></html>
